import type { Router } from 'vue-router';

// One leading '/' and a real route (not the catch-all 404); rejects absolute, protocol-relative and javascript: URLs.
export function isResolvableAppPath(router: Router, path: unknown): path is string {
  if (typeof path !== 'string' || !/^\/(?!\/)/.test(path)) return false;
  try {
    const resolved = router.resolve(path);
    if (!resolved.matched.length) return false;
    return !resolved.matched.some((r) => r.path === '/:catchAll(.*)*');
  } catch {
    return false;
  }
}
